{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Acarbose, a polar oligosaccharide, has an absolute oral bioavailability of <2% in humans; its polyhydroxylated glycoside structure and negligible absorption support a low F for the query's polar sulfated disaccharide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pentosan polysulfate, a sulfated polysaccharide, has an oral bioavailability of ≤3% in humans, providing direct evidence that sulfated carbohydrate structures are very poorly absorbed and supporting low F for the sulfated sugar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Dextran sulfate, a heavily sulfated carbohydrate, is reported to have poor oral bioavailability in humans, supporting low absorption for the sulfated glycoside query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Tobramycin, a polar aminosugar antibiotic, has low and virtually negligible oral bioavailability in patients, supporting low F for the N-acetylglucosamine-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Furosemide acyl glucuronide has a measured human oral F of 0.15 ± 0.04, below the 20% threshold; this carboxylate-containing glucuronide supports low F for the glucuronic-acid-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Scutellarin, a glucuronide glycoside, has an estimated human oral bioavailability of only 10.67%, supporting low F for the query's glucuronic acid glycoside motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Glycyrrhizin, a glucuronic-acid-containing glycoside, has an oral bioavailability of approximately 0.25% compared with injections in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Thiocolchicoside, a glycoside, has an oral bioavailability of 0.27 relative to intramuscular dosing in healthy volunteers, supporting low F for glycoside-type structures like the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, ionizable sulfated N-acetylglucosamine-glucuronic acid disaccharide. All transferable experimental evidence from polar glycosides, sulfated carbohydrates, glucuronides, and aminosugars shows oral bioavailability well below 20% (e.g., <2% for acarbose, ≤3% for pentosan polysulfate, 0.15 for furosemide acyl glucuronide). Although Morgan similarities are modest, the shared physicochemical liabilities—multiple hydrogen-bond donors/acceptors, negative charges, and high polarity—make low oral bioavailability the only well-supported prediction.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query disaccharide in humans or animals.",
    "Morgan similarity scores are low (0.22–0.28), so transferability is limited by structural differences.",
    "No evidence addresses possible prodrug behavior, active uptake, or degradation to absorbable fragments for this specific disaccharide."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

